items.solution:
function canAccessAll(grants, role, table, operations) {
  const ops = grants[role]?.[table];
  if (!Array.isArray(ops) || operations.length === 0) return false;
  return operations.every((op) => ops.includes(op));
}

function allowedTables(grants, role, operation) {
  const tables = grants[role] ?? {};
  return Object.keys(tables)
    .filter((t) => tables[t].includes(operation))
    .sort();
}

function firstDenied(grants, role, requests) {
  return requests.findIndex(({ table, operation }) => {
    const ops = grants[role]?.[table];
    return !(Array.isArray(ops) && ops.includes(operation));
  });
}
